-- ========================================================================
-- BEGIN 08_create_table_nursing_care_plan_grade.sql
-- ========================================================================

-- Computed completeness grading result for a nursing care plan. Stores the
-- overall completeness status (Complete / Partial / Incomplete) and the
-- completeness percent derived by the engine from the plan's problems, goals,
-- interventions, and evaluations.

CREATE TABLE nursing_care_plan_grade (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    nursing_care_plan_id UUID NOT NULL UNIQUE
        REFERENCES nursing_care_plan(id) ON DELETE CASCADE,

    status VARCHAR(15) NOT NULL DEFAULT ''
        CHECK (status IN ('complete', 'partial', 'incomplete', '')),
    completeness_percent INTEGER NOT NULL DEFAULT 0
        CHECK (completeness_percent BETWEEN 0 AND 100),
    graded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER trigger_nursing_care_plan_grade_updated_at
    BEFORE UPDATE ON nursing_care_plan_grade
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE nursing_care_plan_grade IS
    'Computed completeness grading result for a nursing care plan: overall status and completeness percent.';
COMMENT ON COLUMN nursing_care_plan_grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN nursing_care_plan_grade.created_at IS
    'Timestamp when the row was created.';
COMMENT ON COLUMN nursing_care_plan_grade.updated_at IS
    'Timestamp when the row was most recently updated.';
COMMENT ON COLUMN nursing_care_plan_grade.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN nursing_care_plan_grade.nursing_care_plan_id IS
    'Foreign key to the parent nursing care plan (unique, 1:1).';
COMMENT ON COLUMN nursing_care_plan_grade.status IS
    'Overall completeness status: complete, partial, or incomplete.';
COMMENT ON COLUMN nursing_care_plan_grade.completeness_percent IS
    'Proportion (0-100) of the three required elements (goal, intervention, evaluation) present across all problems.';
COMMENT ON COLUMN nursing_care_plan_grade.graded_at IS
    'Timestamp when the engine last computed the grade.';

-- ========================================================================
-- END 08_create_table_nursing_care_plan_grade.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 09_create_table_nursing_care_plan_grade_rule.sql
-- ========================================================================

-- Audit trail of every completeness rule that fired during grading. Each row
-- records one rule firing with a category and a human-readable description.

CREATE TABLE nursing_care_plan_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    nursing_care_plan_grade_id UUID NOT NULL
        REFERENCES nursing_care_plan_grade(id) ON DELETE CASCADE,

    rule_id VARCHAR(40) NOT NULL,
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX nursing_care_plan_grade_rule_grade_id_idx
    ON nursing_care_plan_grade_rule (nursing_care_plan_grade_id);

CREATE TRIGGER trigger_nursing_care_plan_grade_rule_updated_at
    BEFORE UPDATE ON nursing_care_plan_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE nursing_care_plan_grade_rule IS
    'Audit trail of every completeness rule that fired during grading: category and description.';
COMMENT ON COLUMN nursing_care_plan_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN nursing_care_plan_grade_rule.created_at IS
    'Timestamp when the row was created.';
COMMENT ON COLUMN nursing_care_plan_grade_rule.updated_at IS
    'Timestamp when the row was most recently updated.';
COMMENT ON COLUMN nursing_care_plan_grade_rule.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN nursing_care_plan_grade_rule.nursing_care_plan_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN nursing_care_plan_grade_rule.rule_id IS
    'Stable rule identifier (e.g. R-PROBLEM-COMPLETE-01).';
COMMENT ON COLUMN nursing_care_plan_grade_rule.category IS
    'Subject category (e.g. problem-completeness, plan-status).';
COMMENT ON COLUMN nursing_care_plan_grade_rule.description IS
    'Human-readable description of why the rule fired.';

-- ========================================================================
-- END 09_create_table_nursing_care_plan_grade_rule.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 10_create_table_nursing_care_plan_grade_flag.sql
-- ========================================================================

-- Flagged issues raised independently of the completeness status, with a
-- priority and a suggested action for the nursing team.

CREATE TABLE nursing_care_plan_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    nursing_care_plan_grade_id UUID NOT NULL
        REFERENCES nursing_care_plan_grade(id) ON DELETE CASCADE,

    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'risk-without-intervention',
            'high-risk-not-actioned',
            'missing-evaluation',
            'unmet-goal-overdue',
            'no-review-date',
            'incomplete-problem',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX nursing_care_plan_grade_flag_grade_id_idx
    ON nursing_care_plan_grade_flag (nursing_care_plan_grade_id);

CREATE TRIGGER trigger_nursing_care_plan_grade_flag_updated_at
    BEFORE UPDATE ON nursing_care_plan_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE nursing_care_plan_grade_flag IS
    'Flagged issues raised independently of the completeness status, with priority and a suggested action for the nursing team.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.created_at IS
    'Timestamp when the row was created.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.updated_at IS
    'Timestamp when the row was most recently updated.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.nursing_care_plan_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.flag_id IS
    'Stable flag identifier (e.g. F-RISK-WITHOUT-INTERVENTION-001).';
COMMENT ON COLUMN nursing_care_plan_grade_flag.category IS
    'Flag category: risk-without-intervention, high-risk-not-actioned, missing-evaluation, unmet-goal-overdue, no-review-date, incomplete-problem, or other.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.priority IS
    'Priority: low, medium, high.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.description IS
    'Human-readable description of what fired the flag.';
COMMENT ON COLUMN nursing_care_plan_grade_flag.suggested_action IS
    'Suggested nursing action (e.g. "add an intervention for the high falls risk").';

-- ========================================================================
-- END 10_create_table_nursing_care_plan_grade_flag.sql
-- ========================================================================
